-- Register definitions for the example_axi module.
--
-- Generated by bust. Registers and fields are expressed as nested records
-- (regs.<reg>.<field>) so the module stays one record signal and the hardware
-- sees each field by name with its modifiers attached.
--
-- Three record families, all nested register -> field:
--   t_example_axi_regs      internal storage (one per field that holds state)
--   t_example_axi_to_hw     regfile -> hardware (hw r / rw field values)
--   t_example_axi_from_hw   hardware -> regfile (hw w / rw values + modifiers)
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

use work.example_axi_localbus_pkg.all;

package example_axi_regfile_pkg is

  constant C_ADDR_REG0 : std_logic_vector(31 downto 0) := 32x"00";
  constant C_ADDR_REG1 : std_logic_vector(31 downto 0) := 32x"04";
  constant C_ADDR_REG2 : std_logic_vector(31 downto 0) := 32x"08";
  constant C_ADDR_REG3 : std_logic_vector(31 downto 0) := 32x"0C";
  constant C_ADDR_REG4 : std_logic_vector(31 downto 0) := 32x"10";
  constant C_ADDR_REG5 : std_logic_vector(31 downto 0) := 32x"14";
  constant C_ADDR_REG6 : std_logic_vector(31 downto 0) := 32x"18";
  constant C_ADDR_REG7 : std_logic_vector(31 downto 0) := 32x"1C";
  constant C_ADDR_REG8 : std_logic_vector(31 downto 0) := 32x"20";
  constant C_ADDR_REG9 : std_logic_vector(31 downto 0) := 32x"24";
  constant C_ADDR_REG10 : std_logic_vector(31 downto 0) := 32x"28";
  constant C_ADDR_REG11 : std_logic_vector(31 downto 0) := 32x"2C";

  -- Register-select width: the low address bits that pick a register. It is the
  -- smallest module address width that holds the registers, and the default of
  -- the G_MODULE_ADDR_WIDTH generic.
  constant C_MODULE_ADDR_WIDTH : natural := 6;

  -- Internal storage, one record per register, each member a field that holds
  -- state (every software- or hardware-writable field).
  type t_reg0_regs is record
    reg0 : std_logic;
  end record;
  type t_reg1_regs is record
    reg1 : std_logic;
  end record;
  type t_reg2_regs is record
    reg2 : std_logic;
  end record;
  type t_reg3_regs is record
    reg3 : std_logic_vector(7 downto 0);
  end record;
  type t_reg4_regs is record
    reg4 : std_logic_vector(13 downto 0);
  end record;
  type t_reg5_regs is record
    reg5 : std_logic_vector(31 downto 0);
  end record;
  type t_reg6_regs is record
    reg6 : std_logic_vector(31 downto 0);
  end record;
  type t_reg7_regs is record
    field0 : std_logic;
    field1 : std_logic_vector(3 downto 0);
    field2 : std_logic;
    field3 : std_logic_vector(14 downto 0);
  end record;
  type t_reg8_regs is record
    field0 : std_logic;
    field1 : std_logic_vector(18 downto 0);
    field2 : std_logic;
    field3 : std_logic_vector(2 downto 0);
  end record;
  type t_reg9_regs is record
    reg9 : std_logic;
  end record;
  type t_reg10_regs is record
    reg10 : std_logic_vector(3 downto 0);
  end record;
  type t_reg11_regs is record
    field0 : std_logic_vector(14 downto 0);
    field1 : std_logic;
  end record;

  -- Whole-module storage: the regfile keeps this as a single signal.
  type t_example_axi_regs is record
    reg0 : t_reg0_regs;
    reg1 : t_reg1_regs;
    reg2 : t_reg2_regs;
    reg3 : t_reg3_regs;
    reg4 : t_reg4_regs;
    reg5 : t_reg5_regs;
    reg6 : t_reg6_regs;
    reg7 : t_reg7_regs;
    reg8 : t_reg8_regs;
    reg9 : t_reg9_regs;
    reg10 : t_reg10_regs;
    reg11 : t_reg11_regs;
  end record;

  constant C_EXAMPLE_AXI_REGS_RESET : t_example_axi_regs := (
    reg0 => (reg0 => '0'),
    reg1 => (reg1 => '1'),
    reg2 => (reg2 => '0'),
    reg3 => (reg3 => 8X"3"),
    reg4 => (reg4 => (others => '0')),
    reg5 => (reg5 => 32X"FFFFFFFF"),
    reg6 => (reg6 => (others => '0')),
    reg7 => (field0 => '1', field1 => 4X"B", field2 => '0', field3 => 15X"2B"),
    reg8 => (field0 => '0', field1 => (others => '0'), field2 => '0', field3 => (others => '0')),
    reg9 => (reg9 => '1'),
    reg10 => (reg10 => 4X"A"),
    reg11 => (field0 => 15X"3", field1 => '0'));

  -- regfile -> hardware: only fields the hardware can read (hw r / rw). Fields
  -- with a software-access pulse (swmod/swacc) pair the value with the strobe.
  -- A register without fields has no record of its own: its value, or its
  -- value-and-strobe record, is the register's member of the bundle.
  type t_reg7_to_hw is record
    field0 : std_logic;
    field1 : std_logic_vector(3 downto 0);
    field2 : std_logic;
    field3 : std_logic_vector(14 downto 0);
  end record;
  type t_reg11_to_hw is record
    field0 : std_logic_vector(14 downto 0);
    field1 : std_logic;
  end record;

  -- Whole-module regfile -> hardware bundle.
  type t_example_axi_to_hw is record
    reg0 : std_logic;
    reg1 : std_logic;
    reg3 : std_logic_vector(7 downto 0);
    reg5 : std_logic_vector(31 downto 0);
    reg7 : t_reg7_to_hw;
    reg9 : std_logic;
    reg10 : std_logic_vector(3 downto 0);
    reg11 : t_reg11_to_hw;
  end record;

  -- hardware -> regfile: per-field input records pairing each value with the
  -- modifier strobes that gate it. A field gets its own record only when it
  -- carries a strobe (we/wel/set/clr); a plain continuous input is a bare member.
  type t_reg8_from_hw is record
    field0 : std_logic;
    field1 : std_logic_vector(18 downto 0);
    field2 : std_logic;
    field3 : std_logic_vector(2 downto 0);
  end record;

  -- Whole-module hardware -> regfile bundle.
  type t_example_axi_from_hw is record
    reg2 : std_logic;
    reg4 : std_logic_vector(13 downto 0);
    reg6 : std_logic_vector(31 downto 0);
    reg8 : t_reg8_from_hw;
  end record;

  -- The module answers for an address range of 2**module_addr_width addresses
  -- from its base address. module_addr_width is the register file's
  -- G_MODULE_ADDR_WIDTH generic: the low module_addr_width bits of an address
  -- give its place in the range, and the bits above them the base address. The
  -- low C_MODULE_ADDR_WIDTH bits select the register.

  -- True when check is false, or when the base address bits of addr equal the
  -- same bits of base.
  function base_match(addr              : std_logic_vector(31 downto 0);
                      base              : unsigned(31 downto 0);
                      check             : boolean;
                      module_addr_width : natural) return boolean;

  -- True when a bit of addr from C_MODULE_ADDR_WIDTH up to module_addr_width is
  -- set, so the address is above the registers in the address range. Such an
  -- address gets an error response instead of reaching a register through its
  -- low bits.
  function above_registers(addr              : std_logic_vector(31 downto 0);
                           module_addr_width : natural) return boolean;

  function sel_is(sel      : std_logic_vector(C_MODULE_ADDR_WIDTH-1 downto 0);
                  reg_addr : std_logic_vector(31 downto 0)) return boolean;

  function is_mapped(sel : std_logic_vector(C_MODULE_ADDR_WIDTH-1 downto 0)) return boolean;

end package example_axi_regfile_pkg;

package body example_axi_regfile_pkg is

  function base_match(addr              : std_logic_vector(31 downto 0);
                      base              : unsigned(31 downto 0);
                      check             : boolean;
                      module_addr_width : natural) return boolean is
    constant base_slv : std_logic_vector(31 downto 0) := std_logic_vector(base);
  begin
    if not check then
      return true;
    end if;
    return addr(31 downto module_addr_width)
         = base_slv(31 downto module_addr_width);
  end function;

  function above_registers(addr              : std_logic_vector(31 downto 0);
                           module_addr_width : natural) return boolean is
  begin
    for i in C_MODULE_ADDR_WIDTH to module_addr_width - 1 loop
      if addr(i) /= '0' then
        return true;
      end if;
    end loop;
    return false;
  end function;

  function sel_is(sel      : std_logic_vector(C_MODULE_ADDR_WIDTH-1 downto 0);
                  reg_addr : std_logic_vector(31 downto 0)) return boolean is
  begin
    return sel = reg_addr(C_MODULE_ADDR_WIDTH-1 downto 0);
  end function;

  function is_mapped(sel : std_logic_vector(C_MODULE_ADDR_WIDTH-1 downto 0)) return boolean is
  begin
    return sel_is(sel, C_ADDR_REG0) or sel_is(sel, C_ADDR_REG1) or sel_is(sel, C_ADDR_REG2) or sel_is(sel, C_ADDR_REG3) or sel_is(sel, C_ADDR_REG4) or sel_is(sel, C_ADDR_REG5) or sel_is(sel, C_ADDR_REG6) or sel_is(sel, C_ADDR_REG7) or sel_is(sel, C_ADDR_REG8) or sel_is(sel, C_ADDR_REG9) or sel_is(sel, C_ADDR_REG10) or sel_is(sel, C_ADDR_REG11);
  end function;

end package body example_axi_regfile_pkg;
